// expr := term (('+'|'-') term)*      <- 덧셈은 바깥
// term := atom (('*'|'/') atom)*      <- 곱셈은 안쪽 (먼저 묶인다)
// atom := 숫자 | 이름 | '(' expr ')'

function expr() {
  let node = term();
  while (peek()?.v === '+' || peek()?.v === '-') {
    const op = next().v;
    node = { t: 'bin', op, l: node, r: term() };
  }
  return node;
}

function evalNode(n, env) {
  if (n.t === 'num') return n.v;
  if (n.t === 'var') return env[n.v] ?? err('모르는 이름: ' + n.v);
  const l = evalNode(n.l, env), r = evalNode(n.r, env);
  switch (n.op) {
    case '+': return l + r;
    case '-': return l - r;
    case '*': return l * r;
    case '/': return r === 0 ? err('0으로 나눔') : l / r;
  }
}

